# modules/s3-bucket: a minimal well-interfaced module
# modules/s3-bucket/variables.tf
variable "bucket_name" {
  type        = string
  description = "Globally unique bucket name"
}
variable "versioning" {
  type        = bool
  default     = true
  description = "Enable object versioning"
}

# modules/s3-bucket/main.tf
resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name
}
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration { status = var.versioning ? "Enabled" : "Suspended" }
}

# modules/s3-bucket/outputs.tf
output "arn" { value = aws_s3_bucket.this.arn }

# Root as wiring diagram: thin, declarative, architectural
module "network" {
  source   = "./modules/network"
  vpc_cidr = "10.0.0.0/16"
  az_count = 3
}

module "cluster" {
  source     = "./modules/eks"
  subnet_ids = module.network.private_subnet_ids  # wiring
  vpc_id     = module.network.vpc_id
}

module "app" {
  for_each   = var.services          # one per service
  source     = "./modules/app"
  cluster_id = module.cluster.id
  image      = each.value.image
}

# Calling with version discipline
module "vpc" {
  source  = "app.terraform.io/acme/vpc/aws"
  version = "~> 3.2"   # >=3.2, <4.0: minor+patch float, major pinned

  vpc_cidr = "10.0.0.0/16"
}

