// Terratest: the module's contract, proven against real infrastructure
package test

import "testing"
import "github.com/gruntwork-io/terratest/modules/terraform"

func TestS3SecureModule(t *testing.T) {
  opts := terraform.WithDefaultRetryableErrors(t, &terraform.Options{
    TerraformDir: "../examples/basic",
    Vars: map[string]interface{}{
      "bucket_name": "terratest-" + random.UniqueId(),
    },
  })
  defer terraform.Destroy(t, opts)   // always clean up
  terraform.InitAndApply(t, opts)
  arn := terraform.Output(t, opts, "arn")
  assert.Contains(t, arn, "arn:aws:s3:::")
  // + AWS API assertions: versioning enabled, encryption on
}

# terraform { cloud } : the modern TFC integration
terraform {
  cloud {
    organization = "acme"
    workspaces {
      tags = ["prod", "network"]  # runs in all matching workspaces
    }
  }
}

# Run lifecycle (remote execution):
#   VCS push / CLI / API  ->  plan (remote runner)
#     -> cost estimate + policy check
#       -> human confirm (or auto-apply)
#         -> apply  ->  state + history recorded

# Sentinel: require S3 encryption (hard-mandatory for prod)
# main.sentinel
import "tfplan/v2" as tfplan

s3_buckets = filter tfplan.resource_changes as _, rc {
  rc.type is "aws_s3_bucket" and rc.mode is "managed"
}

violations = filter s3_buckets as _, rc {
  rc.change.after.server_side_encryption_configuration is undefined
}

main = rule {
  length(violations) is 0
}
# policy set: hard-mandatory on prod workspaces, advisory elsewhere

# template.pkr.hcl: one definition, AMI + Docker
packer {
  required_plugins {
    amazon = { source = "github.com/hashicorp/amazon", version = "~> 1" }
  }
}

source "amazon-ebs" "web" {
  ami_name      = "web-{{timestamp}}"
  instance_type = "t3.micro"
  region        = "us-east-1"
  source_ami_filter {
    filters     = { name = "amzn2-ami-hvm-*", virtualization-type = "hvm" }
    owners      = ["amazon"]
    most_recent = true
  }
  ssh_username = "ec2-user"
}

build {
  sources = ["source.amazon-ebs.web"]
  provisioner "ansible" {
    playbook_file = "../ansible/web.yml"
  }
}

build {
  sources = ["source.amazon-ebs.web"]

  provisioner "shell" {
    inline = ["sudo yum update -y", "sudo yum install -y python3"]
  }
  provisioner "ansible" {
    playbook_file = "../ansible/web.yml"   # SAME roles as deploy-time
  }
  provisioner "shell" {
    inline = [
      "sudo rm -rf /tmp/* /var/log/*.log",
      "sudo shred -u /home/ec2-user/.bash_history || true",
    ]
  }
}

